/**
 * 页脚上的页码：数字本身就能改。
 *
 * 平时它只是「第几页 / 共几页」里那个安安静静的数字；点一下数字变成可写，
 * 敲页码回车（或点到别处）就翻过去 —— 想翻到很后面的一页不必一路点箭头。
 * 数字挤不出行：输入框宽度按总页数的位数撑开，跳页前后那一栏都不动。
 */
import { useEffect, useState } from "react";
import { cn } from "../../lib/cn";
import "./page-jump.css";

export interface PageJumpProps {
  /** 当前第几页（从 1 数）。 */
  page: number;
  total: number;
  /** 落到哪一页。已经在这一页就不会喊。 */
  onJump: (page: number) => void;
  /** 数字后面跟着的量词，比如「开」。 */
  unit?: string;
  className?: string;
}

export function PageJump({
  page,
  total,
  onJump,
  unit,
  className,
}: PageJumpProps) {
  const safeTotal = Math.max(total, 1);
  const [draft, setDraft] = useState(String(page));
  const [editing, setEditing] = useState(false);

  // 翻页、跳页之后数字跟着走；手上正在写的草稿不抢。
  useEffect(() => {
    if (!editing) setDraft(String(page));
  }, [page, editing]);

  const commit = () => {
    setEditing(false);
    const parsed = Number.parseInt(draft.replace(/[^0-9]/g, ""), 10);
    const target = Number.isFinite(parsed)
      ? Math.min(Math.max(parsed, 1), safeTotal)
      : page;
    setDraft(String(target));
    if (target !== page) onJump(target);
  };

  return (
    <span className={cn("page-jump", className)}>
      {/* 宽度跟着字走：平时照总页数几位就几位，写的时候多打一位也放得下。 */}
      <input
        className="page-jump__input"
        type="text"
        inputMode="numeric"
        pattern="[0-9]*"
        value={draft}
        style={{
          width: `${Math.max(2, String(safeTotal).length, draft.length)}ch`,
        }}
        aria-label={`跳到第几页，共 ${safeTotal} 页`}
        title="输入页码，回车跳过去"
        onFocus={(event) => {
          setEditing(true);
          event.currentTarget.select();
        }}
        onChange={(event) =>
          setDraft(event.target.value.replace(/[^0-9]/g, "").slice(0, 4))
        }
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            event.stopPropagation();
            event.currentTarget.blur();
          } else if (event.key === "Escape") {
            event.stopPropagation();
            setDraft(String(page));
            event.currentTarget.blur();
          }
        }}
        onBlur={commit}
      />
      <span className="page-jump__sep" aria-hidden="true">
        /
      </span>
      <span className="page-jump__total">
        {safeTotal}
        {unit}
      </span>
    </span>
  );
}
